// Structural step table for the T8 correction. Not an experiment version.
// Do not edit this file after it has run.
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const POSE = '09cb38618024a749ba4b15ee3be4e5140257d6c5145347567887196a81665358';
const AF_TAB_HEADER = 'bb086a5b20fe141fc7db882c015fb47fa34bccd9d86ab709799ef8bb8324225c';
const AF_TAB_TITLE = '2.AF';
const STOCK = [14, 2, 2, 0, 27, 0, 39, 0, 0, 0];
const ALL_PRESS = [14, 2, 2, 0, 1, 0, 1, 0, 0, 0];
const ROLES = ['k1', 'k2', 'c1', 'c2'];
const CAND = ['c1', 'c2'];

function zeros() { return Array.from({ length: 55 }, () => 0); }
function putU16(m, off, v) { m[off] = v & 0xff; m[off + 1] = (v >> 8) & 0xff; }

const POS1 = 994;
const POS5 = 117;

function mirrorSmall() {
  const m = zeros();
  m[1] = 2;
  putU16(m, 12, POS1);
  putU16(m, 34, POS1);
  return m;
}
function mirrorExif() {
  const m = mirrorSmall();
  m[5] = 2;
  putU16(m, 20, POS5);
  return m;
}
function mirrorZone6() {
  const m = mirrorExif();
  m[1] = 6;
  return m;
}
function mirrorC1() {
  const m = mirrorZone6();
  m[24] = 5;
  m[25] = 7;
  return m;
}
function mirrorSize() {
  const m = mirrorC1();
  m[8] = 4;
  return m;
}
function targetAt(pos, kind, size, vw, hw) {
  return [pos & 0xff, (pos >> 8) & 0xff, kind, size, vw, 0, hw, 0, 0, 0];
}
const SMALL_T = targetAt(POS1, 3, 0, 1, 1);
const C1_T = targetAt(POS1, 7, 0, 5, 7);
const SIZE_T = targetAt(POS1, 7, 4, 5, 7);
const EXIF_T = targetAt(POS5, 3, 0, 1, 1);

const EDGES = [
  ['s1', 'down'], ['s1', 'up'],
  ['afon', 'down'], ['afon', 'up'],
  ['s1', 'down'], ['afon', 'down'], ['afon', 'up'], ['s1', 'up'],
  ['afon', 'down'], ['s1', 'down'], ['s1', 'up'], ['afon', 'up'],
];
const AFON = new Set([2, 5, 8, 9, 10]);
const OWNER = [1, 0, 2, 0, 1, 2, 1, 0, 2, 2, 2, 0];

const steps = [];
function add(step) { steps.push(step); return step; }
function shared(id, action, extra, expect) {
  return add({
    id, action, who: ROLES.slice(), editor: false, phase: extra.phase || 'main',
    key: extra.key ?? null, dir: extra.dir ?? null, dial: extra.dial ?? null,
    note: extra.note || '',
    expect: expect || { subject: 0 },
  });
}
function edit(id, action, extra, expect) {
  return add({
    id, action, who: CAND.slice(), editor: true, phase: 'main',
    key: extra.key ?? null, dir: extra.dir ?? null, dial: extra.dial ?? null,
    bound: extra.bound ?? null, until: extra.until ?? null, dials: extra.dials ?? null,
    note: extra.note || 'AF-ON editor key. K1 and K2 skip it.',
    expect,
  });
}

shared('setup', 'setup', {}, { subject: 0, screen: 'shooting' });
shared('zone-up', 'key', { key: 'up', note: 'Native half-press key on the direct screen.' }, { subject: 0 });
shared('zone-ok', 'key', { key: 'ok', note: 'Native half-press key. Leaves the direct screen.' }, { subject: 0 });

edit('e-enter', 'enter', { note: 'AF-ON entry. Mirror initialises from FF to zeros.' }, {
  subject: 0, screen: 'shooting', flag: 1, mirror: zeros(),
});
edit('e-up', 'key', { key: 'up', note: 'Opens the direct editor.' }, {
  subject: 0, screen: 'direct', flag: 1, mirrorZone: { bank: 1, eq: 1 },
});
edit('e-dial', 'dial', { dial: 'main', note: 'One detent, Single to Small.' }, {
  subject: 0, screen: 'direct', flag: 1, mirrorZone: { bank: 1, eq: 2 },
});
edit('e-right', 'key', { key: 'right', note: 'Moves the bank-1 position.' }, {
  subject: 0, screen: 'direct', flag: 1, mirror: mirrorSmall(),
});
edit('e-ok', 'key', { key: 'ok', note: 'Exit with OK.' }, {
  subject: 0, screen: 'shooting', flag: 0, mirror: mirrorSmall(),
});

shared('n-up', 'key', { key: 'up', note: 'Normal edit. Half-press must match K2.' }, { subject: 0 });
shared('n-dial', 'dial', { dial: 'main', note: 'Normal edit. One detent. The recorded cells are the Cross detent, not Single.' }, { subject: 0 });
shared('n-ok', 'key', { key: 'ok' }, { subject: 0 });

EDGES.forEach((pair, i) => {
  const owned = AFON.has(i);
  shared('edge-' + i, 'edge', { key: pair[0], dir: pair[1], note: owned ? 'AF-ON-owned edge.' : 'Half-press edge.' }, {
    subject: 0,
    owner: { k1: 255, c1: OWNER[i], c2: OWNER[i] },
    status: { k1: 255, c1: 0, c2: 0 },
    enabled: { k1: 255, c1: 1, c2: 1 },
    target: owned
      ? { k1: STOCK, c1: SMALL_T, c2: SMALL_T }
      : { k1: STOCK, ref: 'k2' },
  });
});

shared('pose-exif6', 'pose', { key: 'exif6', note: 'Pose stand-in. EXIF 6 selects bank 5.' }, {
  subject: 0, poseIndex: 2, poseExif: 6, poseWord: 2,
});
edit('p-enter', 'enter', { note: 'Re-enter in EXIF 6. Bank 1 stays.' }, {
  subject: 0, flag: 1, mirror: mirrorSmall(),
});
edit('p-up', 'key', { key: 'up', note: 'Opens the direct editor in EXIF 6.' }, {
  subject: 0, screen: 'direct', flag: 1, mirror: mirrorSmall(),
});
edit('p-right', 'key', { key: 'right', note: 'Bank 5 position changes. Bank 1 does not.' }, {
  subject: 0, screen: 'direct', flag: 1, mirror: mirrorExif(),
});
edit('p-menu', 'key', { key: 'menu', note: 'Exit with MENU.' }, {
  subject: 0, flag: 0, mirror: mirrorExif(),
});
shared('exif6-afon-down', 'edge', { key: 'afon', dir: 'down', note: 'AF-ON down in EXIF 6 uses bank 5.' }, {
  subject: 0,
  owner: { k1: 255, c1: 2, c2: 2 },
  target: { k1: STOCK, c1: EXIF_T, c2: EXIF_T },
});
shared('exif6-afon-up', 'edge', { key: 'afon', dir: 'up' }, {
  subject: 0,
  owner: { k1: 255, c1: 0, c2: 0 },
  target: { k1: STOCK, ref: 'k2' },
});
shared('pose-land', 'pose', { key: 'landscape', note: 'Return to landscape. Bank 1.' }, {
  subject: 0, poseIndex: 1, poseExif: 1,
});
shared('land-afon-down', 'edge', { key: 'afon', dir: 'down', note: 'AF-ON down in landscape uses bank 1.' }, {
  subject: 0,
  owner: { k1: 255, c1: 2, c2: 2 },
  target: { k1: STOCK, c1: SMALL_T, c2: SMALL_T },
});
shared('land-afon-up', 'edge', { key: 'afon', dir: 'up' }, {
  subject: 0,
  owner: { k1: 255, c1: 0, c2: 0 },
  target: { k1: STOCK, ref: 'k2' },
});

edit('c-enter', 'enter', { note: 'AF-ON entry before C1.' }, {
  subject: 0, flag: 1, mirror: mirrorExif(),
});
edit('c-up', 'key', { key: 'up', note: 'Opens the direct editor for the C1 selection.' }, {
  subject: 0, screen: 'direct', flag: 1,
});
edit('c-zone', 'dial-until', {
  dial: 'main', bound: 12, until: { offset: 1, eq: 6 },
  note: 'Selects C1. Zone type 6, not Small (2).',
}, {
  subject: 0, screen: 'direct', flag: 1, mirror: mirrorZone6(),
});
edit('c-dims', 'dial-until', {
  dials: ['sub', 'main'], bound: 24, until: { all: [{ offset: 24, eq: 5 }, { offset: 25, eq: 7 }] },
  note: 'Custom sizes [5,7] at mirror 0x1dd1[2] and [3].',
}, {
  subject: 0, screen: 'direct', flag: 1, mirror: mirrorC1(),
});
edit('c-s1', 'key', { key: 's1', note: 'Exit with S1 while the direct editor is open.' }, {
  subject: 0, flag: 0, mirror: mirrorC1(),
});

shared('n2-up', 'key', { key: 'up', note: 'Normal edit after the S1 exit.' }, { subject: 0 });
shared('n2-dial', 'dial', { dial: 'main' }, { subject: 0 });
shared('n2-ok', 'key', { key: 'ok' }, { subject: 0 });
shared('c-afon-down', 'edge', { key: 'afon', dir: 'down', note: 'AF-ON press gives the C1 record.' }, {
  subject: 0,
  owner: { k1: 255, c1: 2, c2: 2 },
  target: { k1: STOCK, c1: C1_T, c2: C1_T },
  sizeRecord: { ref: 'k2' },
});
shared('c-afon-up', 'edge', { key: 'afon', dir: 'up' }, {
  subject: 0,
  owner: { k1: 255, c1: 0, c2: 0 },
  target: { k1: STOCK, ref: 'k2' },
  sizeRecord: { ref: 'k2' },
});

edit('size-write', 'size-setup', {
  note: 'The editor cannot set mirror 0x9a41[0]. Labelled test-setup write of 4. EMULATOR-ONLY. Role: test setup.',
}, {
  subject: 0, mirror: mirrorSize(),
});
shared('size-afon-down', 'edge', { key: 'afon', dir: 'down', note: 'AF-ON size byte follows the mirror. Half-press size follows live 0x9a41[0].' }, {
  subject: 0,
  owner: { k1: 255, c1: 2, c2: 2 },
  target: { k1: STOCK, c1: SIZE_T, c2: SIZE_T },
  halfSize: { ref: 'k2' },
});
shared('size-afon-up', 'edge', { key: 'afon', dir: 'up' }, {
  subject: 0,
  owner: { k1: 255, c1: 0, c2: 0 },
  target: { k1: STOCK, ref: 'k2' },
});

shared('save-identity', 'save-identity', {
  note: 'Identity-guided save. Bounded search to the T6 AF tab, then the AF Target Mode row, then the commit.',
}, {
  subject: 0,
  afTabHeader: AF_TAB_HEADER,
  afTabTitle: AF_TAB_TITLE,
  highlightRow: 'AF Target Mode',
  baselines: ['storeLog', 'callbacks', 'queue'],
  persistedOffsets: [211472, 211476, 211480, 211484, 211504, 211508, 211512, 211516],
});

function reopen(id, action, extra, expect) {
  return add({
    id, action, who: extra.who || ROLES.slice(), editor: !!extra.editor, phase: 'reopen',
    key: extra.key ?? null, dir: extra.dir ?? null,
    note: extra.note || '',
    expect,
  });
}
reopen('reopen-base', 'check', {}, {
  subject: 0,
  mirror: { k1: 'FF', k2: 'FF', c1: 'FF', c2: 'FF' },
  zone: { c1: 0, c2: 0 },
});
reopen('reopen-afon-down', 'edge', { key: 'afon', dir: 'down' }, {
  subject: 0,
  mirror: { k1: 'FF', k2: 'FF', c1: 'FF', c2: 'FF' },
  zone: { c1: 0, c2: 0 },
  target: { k1: STOCK, c1: ALL_PRESS, c2: ALL_PRESS },
  owner: { k1: 255, c1: 2, c2: 2 },
  focus: { ref: 'k2' },
  active: { ref: 'k2' },
  half: { ref: 'k2' },
});
reopen('reopen-afon-up', 'edge', { key: 'afon', dir: 'up' }, {
  subject: 0,
  mirror: { k1: 'FF', k2: 'FF', c1: 'FF', c2: 'FF' },
  target: { k1: STOCK, ref: 'k2' },
  owner: { k1: 255, c1: 0, c2: 0 },
  focus: { ref: 'k2' },
  active: { ref: 'k2' },
  half: { ref: 'k2' },
});
reopen('reopen-enter', 'enter', {
  who: CAND.slice(), editor: true,
  note: 'Next AF-ON entry initialises the FF mirror.',
}, {
  subject: 0, flag: 1, mirror: zeros(),
});

let candMirror = null;
let candFlag = null;
for (const step of steps) {
  if (step.phase !== 'reopen' && Array.isArray(step.expect.mirror)) candMirror = step.expect.mirror;
  if (step.phase !== 'reopen' && typeof step.expect.flag === 'number') candFlag = step.expect.flag;
  if (!step.editor && step.phase === 'main' && candMirror && !step.expect.mirror) {
    step.expect.mirror = { c1: candMirror.slice(), c2: candMirror.slice() };
  }
  if (!step.editor && step.phase === 'main' && candFlag != null && step.expect.flag == null) {
    step.expect.flag = { c1: candFlag, c2: candFlag };
  }
}
const editorKeys = steps.filter((s) => s.editor).map((s) => ({ id: s.id, note: s.note }));
const ids = steps.map((s) => s.id);
if (new Set(ids).size !== ids.length) throw new Error('duplicate id in builder');

const table = {
  task: 'T8',
  table: 'accept-table-t8-r1',
  poseSha256: POSE,
  afTabHeader: AF_TAB_HEADER,
  afTabTitle: AF_TAB_TITLE,
  stockTarget: STOCK,
  allPress: ALL_PRESS,
  smallTarget: SMALL_T,
  c1Target: C1_T,
  sizeTarget: SIZE_T,
  exifTarget: EXIF_T,
  bank1Position: POS1,
  bank5Position: POS5,
  presetNames: {
    halfCross: 'The one-detent half-press cells are Cross (k99a1[0]=3), recorded by the reference run. The old name halfSingle is not used.',
  },
  editorKeys,
  steps,
};
const out = resolve('work/out/accept-table-t8-r1.json');
writeFileSync(out, JSON.stringify(table, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, steps: steps.length, editorKeys: editorKeys.length }) + '\n');
